export const GUIDE_CATEGORIES = [
  'הכל',
  ...Array.from(new Set(guides.map((g) => g.category))),
]

export const getGuide = (slug: string) => guides.find((g) => g.slug === slug) ?? null

export const guideImg = (id: string, w = 700) =>
  `https://images.unsplash.com/${id}?w=${w}&auto=format&fit=crop&q=55`
